def backfill_units_and_plans(apps, schema_editor):
    PlanVersion = apps.get_model("saas", "PlanVersion")
    BusinessUnit = apps.get_model("saas", "BusinessUnit")
    Company = apps.get_model("saas", "Company")
    previous, _ = PlanVersion.objects.get_or_create(
        code="basic", version=1,
        defaults={"name": "Básico anterior", "included_business_units": 2,
                  "included_whatsapp_numbers": 2,
                  "additional_whatsapp_monthly_price": Decimal("49.90")},
    )
    PlanVersion.objects.get_or_create(
        code="basic", version=2,
        defaults={"name": "Básico", "included_business_units": 2,
                  "included_whatsapp_numbers": 2,
                  "additional_whatsapp_monthly_price": Decimal("30.00")},
    )
    models_to_backfill = (
        "WhatsAppNumber", "KnowledgeBase", "CatalogItem", "MediaAsset",
        "Conversation", "Order", "Sale",
    )
    for company in Company.objects.all().iterator(chunk_size=500):
        Company.objects.filter(pk=company.pk, plan__isnull=True).update(plan=previous)
        unit, _ = BusinessUnit.objects.get_or_create(
            company_id=company.pk, is_default=True,
            defaults={"name": "Geral", "slug": "geral"},
        )
        for name in models_to_backfill:
            apps.get_model("saas", name).objects.filter(
                company_id=company.pk, business_unit__isnull=True,
            ).update(business_unit_id=unit.pk)
    for name in models_to_backfill:
        if apps.get_model("saas", name).objects.filter(business_unit__isnull=True).exists():
            raise RuntimeError(f"Backfill de unidade incompleto: {name}")


